#include <Servo.h>

Servo myServo;
const int servoPin = 9;
int angle = 0;
int stepDir = 1;

void setup() {
  myServo.attach(servoPin);
}

void loop() {
  myServo.write(angle);
  delay(15);
  angle += stepDir;
  if (angle >= 180 || angle <= 0) {
    stepDir = -stepDir;
  }
}
END

