const int IN_SLOT = 1;
const int OUT_SLOT = 2;
bool running = false;

void setup() {
  Serial.begin(115200);
  while (!P1.init()) {
    ;
  }
}

void loop() {
  bool lowLevel = P1.readDiscrete(IN_SLOT, 1);
  bool fullLevel = P1.readDiscrete(IN_SLOT, 2);
  if (lowLevel && !fullLevel) running = true;
  if (fullLevel) running = false;
  P1.writeDiscrete(running, OUT_SLOT, 1);
}
END

